################################################################################
# Lineage 1: SCT reintegration, Monocle3 clustering and Slingshot trajectories
# Converted from the original R Markdown script; analysis steps retained.
# Run from a directory containing the inputs generated by the preceding script.
################################################################################


################################################################################



suppressPackageStartupMessages({
  library(reticulate)
  library(Seurat)
  library(tidyverse)
  library(patchwork)
  library(monocle3)
  library(slingshot)
})

set.seed(123)

reticulate::py_module_available(module='leidenalg')
reticulate::import('leidenalg')

cores = 2
resolution = 0.00004

palette <- c("#5A5156FF", "#E4E1E3FF", "#F6222EFF" ,
             "#FE00FAFF", "#16FF32FF" ,"#3283FEFF",
             "#FEAF16FF", "#B00068FF", "#1CFFCEFF",
             "#90AD1CFF", "#2ED9FFFF" ,"#DEA0DFFF",
             "#AA0EDFFF", "#F8A19FFF", "#325A9BFF" ,
             "#C4451CFF", "#1C8356FF" ,"#85660DFF",
             "#B10DA1FF", "#FBE426FF", "#1CBE4FFF")

################################################################################
######################### scTransform integration ##############################
################################################################################
data <-
  readRDS(
    'Beta_T2D_lineage1.rds'
  )
dim(data)

VlnPlot(
  data,
  features = c('nFeature_RNA', 'nCount_RNA', 'logCounts'),
  group.by = 'monocle_clusters'
)

## No DefaultAssay() call, as in the original run: the lineage input objects were saved with SCT as the default assay,
## so SCTransform below was run on the SCT assay (the input has ~16k features, not the 18,829 of the RNA assay).
data.list <- SplitObject(data, split.by = "study")
rm(data)
gc()

lapply(data.list, dim)

## Exclude datasets with insufficient cells ####
data.list <- data.list[sapply(data.list, function(x) dim(x)[2] > 100)]
gc()

# perform SCTransform normalization
data.list <- lapply(X = data.list,
                    FUN = SCTransform,
                    vars.to.regress = c("nCount_RNA",
                                        "nFeature_RNA",
                                        "percent.mt"),
                    return.only.var.genes = F)
gc()

# select integration features
features <- SelectIntegrationFeatures(data.list)

data.list <- PrepSCTIntegration(object.list = data.list,
                                anchor.features = features)

anchors <-
  FindIntegrationAnchors(
    object.list = data.list,
    k.filter = NA,
    anchor.features = features,
    dims = 1:30
  )

rm(data.list)
gc()

data.integrated <- IntegrateData(anchorset = anchors, dims = 1:30,
                                 normalization.method = 'SCT')

DefaultAssay(data.integrated)
data.integrated <- RunPCA(data.integrated, verbose = FALSE)

ElbowPlot(data.integrated, ndims = 50, reduction = 'pca')

data.integrated <- RunUMAP(
  data.integrated,
  dims = 1:10,  # Adjust to the same number of dimensions used in Monocle3
  reduction = "pca",
  n.neighbors = 15L,  # Matching Monocle3's setting
  metric = "cosine",  # Matching Monocle3's setting
  min.dist = 0.3,  # Matching Monocle3's setting
  seed.use = 42L,  # Set seed for reproducibility, can match Monocle3
  umap.method = "umap-learn",  # (default for Seurat is 'uwot')
  verbose = TRUE
)

# Plot UMAP
DimPlot(data.integrated, reduction = "umap",
        group.by = "Condition",pt.size = 1)


