  group_label_size = 10
)+ggpubr::clean_theme()

N2_2 <- plot_cells(
  cds,
  show_trajectory_graph = FALSE,
  color_cells_by = 'Lineage1_2',
  cell_size = 1,
  group_label_size = 10
)+ggpubr::clean_theme()


M2 + N2_1 + N2_2

saveRDS(sim , 'slingshot_sim_lin1.rds')
saveRDS(cds, 'cds_lin1.rds')   #! added: cds_lin1.rds is read by the figure scripts but was not saved here

################################################################################
### tradeSeq fit across both branches of Lineage 1
### (sce_lin1.rds is read by Figure3_OPQ_tradeSeq_modules_clean.R and Figure3_FigureS5_clean.R)
################################################################################
#! the original lines were not in the script; these were reconstructed and
#! verified against the archived sce_lin1.rds: same dimensions (15,090 genes x 16,733 cells),
#! both lineages, 9 knots, and covariate columns from
#! model.matrix(~ 0 + colData(sim)$study).

suppressPackageStartupMessages(library(tradeSeq))

U <- model.matrix( ~ 0 + colData(sim)$study)
dim(U)

sce <-
  tradeSeq::fitGAM(
    counts = sim@assays@data@listData$counts,
    sds = SlingshotDataSet(sim),
    U = U,
    nknots = 9,
    verbose = T
  )

colData(sce) <-
  cbind(barcode = rownames(colData(sce)), colData(sce))
rownames(colData(sce)) <- colData(sce)$barcode
saveRDS(sce, 'sce_lin1.rds')
rm(sce)
gc()
