data.integrated@meta.data$Lineage1_1 <- sim@colData$slingPseudotime_1
data.integrated@meta.data$Lineage1_2 <- sim@colData$slingPseudotime_2

saveRDS(data.integrated, 'Lin1.beta.reintegrated.rds')

lin1_1_obj <-
  subset(data.integrated, cells = rownames(colData(cds))[!is.na(colData(cds)$Lineage1_1)])
saveRDS(lin1_1_obj, 'Beta_T2D_lineage1_1.rds')

lin1_1_obj <- SetIdent(lin1_1_obj, value = 'assigned_label')
DefaultAssay(lin1_1_obj) <- 'RNA'
lin1_1_obj %>% 
  scCustomize::Percent_Expressing(., features = rownames(.)) %>% 
  write.table(., 'Lineage1_1_sling_perc_expr.tsv',row.names = T,
              col.names = NA, sep = '\t')

lin1_2_obj <- subset(data.integrated, 
                   cells = rownames(colData(cds))[!is.na(colData(cds)$Lineage1_2)])
saveRDS(lin1_2_obj, 'Beta_T2D_lineage1_2.rds')

lin1_2_obj <- SetIdent(lin1_2_obj, value = 'assigned_label')
DefaultAssay(lin1_2_obj) <- 'RNA'
lin1_2_obj %>% 
